<?php

namespace Database\Seeders;

use App\Models\Disease;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

class DiseaseSeeder extends Seeder
{
    public function run(): void
    {
        $diseases = [
            ['Demam Berdarah', 'kesehatan-umum', 'Demam berdarah dengue (DBD) adalah infeksi virus dengue yang ditularkan terutama melalui gigitan nyamuk Aedes. Derajatnya bervariasi dan dapat menjadi berat.', 'Demam tinggi, nyeri kepala/belakang mata, nyeri otot, mual, ruam; tanda bahaya meliputi nyeri perut hebat, muntah terus-menerus, perdarahan, gelisah atau sangat lemas.', 'Virus dengue yang ditularkan nyamuk Aedes yang terinfeksi.', 'Tinggal atau bepergian ke daerah dengan penularan dengue; infeksi dengue sebelumnya dapat meningkatkan risiko dengue berat.', 'Penilaian klinis dan pemeriksaan darah sesuai hari sakit; hasil laboratorium perlu ditafsirkan tenaga kesehatan.', 'Tidak ada antivirus khusus. Cairan, pemantauan, dan perawatan suportif diberikan sesuai kondisi. Hindari aspirin/ibuprofen tanpa arahan dokter karena risiko perdarahan.', 'Cegah gigitan nyamuk, hilangkan genangan, tutup tempat air, gunakan repelan dan kelambu/pakaian pelindung.', 'Segera ke fasilitas kesehatan bila ada tanda bahaya, perdarahan, sulit minum, urine berkurang, sesak, atau kesadaran berubah.'],
            ['Hipertensi', 'kesehatan-umum', 'Hipertensi adalah tekanan darah yang menetap di atas batas diagnosis yang ditentukan pedoman klinis. Sering tidak bergejala, tetapi meningkatkan risiko penyakit jantung, stroke, dan ginjal.', 'Sering tanpa gejala. Tekanan sangat tinggi dapat disertai nyeri dada, sesak, gangguan penglihatan, sakit kepala berat, atau kelemahan mendadak.', 'Dipengaruhi gabungan faktor genetik, usia, kondisi kesehatan, dan gaya hidup.', 'Usia bertambah, riwayat keluarga, konsumsi garam tinggi, kurang aktivitas, berat badan berlebih, merokok, alkohol, penyakit ginjal, dan diabetes.', 'Pengukuran berulang dengan teknik yang benar; kadang pemantauan di rumah/24 jam serta pemeriksaan risiko organ.', 'Perubahan gaya hidup dan obat bila diperlukan berdasarkan penilaian dokter. Jangan menghentikan obat ketika tekanan sudah membaik tanpa arahan.', 'Batasi garam, aktif bergerak, jaga berat badan, tidak merokok, batasi alkohol, dan lakukan pemeriksaan rutin.', 'Konsultasi untuk hasil berulang tinggi. Keadaan darurat seperti nyeri dada, sesak, kebingungan, atau gejala stroke perlu pertolongan segera.'],
            ['Diabetes Tipe 2', 'diet-dan-nutrisi', 'Diabetes tipe 2 terjadi ketika tubuh tidak menggunakan insulin secara efektif dan/atau produksi insulin tidak mencukupi sehingga gula darah meningkat.', 'Sering tanpa gejala; dapat berupa sering haus/berkemih, mudah lelah, pandangan kabur, luka lambat sembuh, atau infeksi berulang.', 'Resistensi insulin dan penurunan fungsi sel beta pankreas, dipengaruhi faktor genetik dan lingkungan.', 'Riwayat keluarga, usia, berat badan berlebih, kurang aktivitas fisik, diabetes gestasional sebelumnya, dan beberapa kondisi metabolik.', 'Pemeriksaan gula darah puasa, HbA1c, atau tes lain sesuai kriteria dan konfirmasi tenaga kesehatan.', 'Rencana individual berupa pola makan, aktivitas fisik, pemantauan, dan obat/insulin bila dibutuhkan.', 'Pemeriksaan berkala, pola makan seimbang, aktivitas fisik rutin, tidur cukup, dan hindari merokok.', 'Periksa bila gejala muncul atau hasil skrining tinggi. Cari bantuan segera untuk muntah, dehidrasi, napas cepat, kebingungan, atau penurunan kesadaran.'],
            ['Asma', 'kesehatan-umum', 'Asma adalah penyakit kronis saluran napas dengan peradangan dan penyempitan yang berubah-ubah, menyebabkan gejala berulang.', 'Mengi, sesak, dada terasa berat, dan batuk; sering memburuk malam/dini hari atau setelah pemicu.', 'Peradangan saluran napas dengan faktor kerentanan genetik dan pemicu lingkungan.', 'Alergi, riwayat keluarga, asap rokok, polusi, alergen, infeksi virus, atau paparan kerja tertentu.', 'Riwayat gejala dan pemeriksaan fungsi paru seperti spirometri bila memungkinkan; evaluasi klinis menentukan diagnosis.', 'Obat pengontrol dan pereda sesuai rencana tertulis dari dokter; teknik inhaler perlu diperiksa berkala.', 'Kenali dan kurangi pemicu, hindari asap rokok, gunakan obat sesuai rencana dan kontrol rutin.', 'Ke IGD bila sesak berat, sulit bicara, bibir kebiruan, atau obat pereda tidak membantu sesuai rencana aksi asma.'],
            ['Maag / GERD', 'kesehatan-umum', 'GERD terjadi ketika isi lambung berulang kali naik ke kerongkongan dan menimbulkan gejala atau komplikasi. Istilah maag sering dipakai untuk berbagai keluhan perut atas.', 'Rasa terbakar di dada/ulu hati, regurgitasi asam, rasa asam di mulut; kadang batuk atau suara serak.', 'Refluks isi lambung; dapat dipengaruhi fungsi sfingter, pola makan, dan kondisi tertentu.', 'Makan besar larut malam, berat badan berlebih, kehamilan, merokok, dan pemicu individual.', 'Berdasarkan gejala dan pemeriksaan; endoskopi atau tes lain bila ada tanda bahaya atau indikasi klinis.', 'Perubahan kebiasaan dan terapi obat sesuai evaluasi tenaga kesehatan; jangan menggunakan obat jangka panjang tanpa penilaian.', 'Makan porsi wajar, tidak berbaring segera setelah makan, identifikasi pemicu, berhenti merokok, dan kelola berat badan.', 'Periksa bila sering kambuh, sulit/nyeri menelan, muntah darah, tinja hitam, berat badan turun tanpa sebab, atau nyeri dada.'],
            ['Flu & Batuk', 'kesehatan-umum', 'Flu adalah infeksi saluran pernapasan akibat virus influenza; batuk juga dapat disebabkan banyak virus atau kondisi lain. Pilek biasa tidak selalu influenza.', 'Demam, batuk, nyeri tenggorokan, pilek, nyeri otot, sakit kepala, dan lelah; derajat gejala bervariasi.', 'Penularan virus melalui droplet/aerosol dan tangan/permukaan yang terkontaminasi.', 'Kontak erat, musim penularan, belum mendapat vaksin influenza, usia lanjut, kehamilan, atau penyakit kronis.', 'Biasanya klinis; tes influenza/COVID-19 dapat dipertimbangkan sesuai situasi dan kebijakan setempat.', 'Istirahat, cairan, dan perawatan gejala. Antivirus influenza tertentu hanya dengan evaluasi dan resep, terutama untuk kelompok berisiko.', 'Vaksinasi sesuai anjuran, cuci tangan, etika batuk, ventilasi baik, dan tinggal di rumah saat sakit.', 'Cari pertolongan untuk sesak, nyeri dada, kebingungan, dehidrasi, bibir kebiruan, atau gejala memburuk/berkepanjangan.'],
            ['Diare', 'kesehatan-umum', 'Diare adalah buang air besar cair atau lembek lebih sering dari biasanya. Risiko utamanya adalah dehidrasi.', 'Tinja cair berulang, kram perut, mual; dehidrasi dapat menyebabkan haus, mulut kering, lemas, dan urine berkurang.', 'Infeksi virus, bakteri, atau parasit; juga dapat dipicu obat, intoleransi, atau kondisi usus.', 'Air/makanan tercemar, sanitasi buruk, kontak dengan orang sakit, usia sangat muda atau lanjut.', 'Riwayat dan pemeriksaan; tes tinja/darah dipertimbangkan untuk gejala berat, lama, berdarah, atau kondisi tertentu.', 'Rehidrasi oral merupakan hal penting; terapi lain sesuai penyebab dan penilaian tenaga kesehatan.', 'Cuci tangan, air minum aman, makanan matang, sanitasi baik, dan vaksin rotavirus untuk anak sesuai jadwal.', 'Segera periksa bila ada darah, demam tinggi, nyeri hebat, tidak mampu minum, tanda dehidrasi, atau terjadi pada bayi/lansia dengan kondisi memburuk.'],
            ['Anemia', 'kesehatan-umum', 'Anemia adalah kondisi ketika kadar hemoglobin atau jumlah sel darah merah tidak mencukupi untuk membawa oksigen secara optimal.', 'Lelah, pucat, lemah, pusing, sesak saat aktivitas, jantung berdebar; gejala bergantung penyebab dan tingkat keparahan.', 'Kekurangan zat besi/nutrisi lain, perdarahan, penyakit kronis, gangguan genetik, atau masalah produksi/penghancuran sel darah.', 'Menstruasi berat, kehamilan, asupan kurang, perdarahan saluran cerna, penyakit kronis, atau riwayat keluarga.', 'Pemeriksaan darah lengkap dan tes lanjutan sesuai dugaan penyebab; tidak semua anemia disebabkan kekurangan zat besi.', 'Penanganan menargetkan penyebab; suplemen hanya bila dianjurkan setelah evaluasi.', 'Pola makan beragam dan pemeriksaan/penanganan penyebab perdarahan atau penyakit kronis.', 'Konsultasi bila lelah/pucat menetap. Pertolongan segera untuk sesak saat istirahat, nyeri dada, pingsan, perdarahan banyak, atau kelemahan berat.'],
            ['TBC', 'kesehatan-umum', 'Tuberkulosis adalah penyakit infeksi oleh bakteri Mycobacterium tuberculosis, paling sering menyerang paru dan dapat menular melalui udara.', 'Batuk menetap, dahak atau darah, demam, keringat malam, berat badan turun, lelah; gejala di luar paru bervariasi.', 'Menghirup partikel udara dari penderita TBC aktif yang menular; bukan melalui berbagi alat makan biasa.', 'Kontak erat, HIV/imunosupresi, malnutrisi, diabetes, merokok, atau tinggal di lingkungan padat.', 'Pemeriksaan dahak/tes molekuler, pencitraan, dan evaluasi klinis sesuai program/pedoman setempat.', 'Kombinasi obat antituberkulosis dalam regimen lengkap yang ditentukan program/dokter; kepatuhan sangat penting.', 'Ventilasi baik, etika batuk, skrining kontak, pengobatan dini, serta vaksin BCG sesuai jadwal nasional.', 'Segera periksa bila batuk lama, batuk darah, berat badan turun, atau kontak erat dengan pasien TBC.'],
            ['Kolesterol Tinggi', 'kesehatan-umum', 'Dislipidemia adalah kadar lipid darah yang tidak sehat, termasuk LDL tinggi atau HDL rendah, dan dapat meningkatkan risiko aterosklerosis.', 'Biasanya tidak menimbulkan gejala; diketahui melalui pemeriksaan darah.', 'Dipengaruhi genetik, pola makan, metabolisme, kondisi medis, serta beberapa obat.', 'Riwayat keluarga, diabetes, hipertensi, merokok, kurang aktivitas, pola makan tinggi lemak jenuh/trans, dan usia.', 'Profil lipid darah ditafsirkan bersama faktor risiko kardiovaskular oleh tenaga kesehatan.', 'Perubahan gaya hidup dan obat penurun lipid bila manfaatnya dinilai sesuai risiko.', 'Pola makan kaya sayur/buah/serat, aktivitas fisik, berhenti merokok, dan kontrol faktor risiko lain.', 'Lakukan skrining sesuai anjuran. Nyeri dada mendadak, sesak, atau gejala stroke memerlukan pertolongan darurat.'],
        ];

        foreach ($diseases as [$name, $category, $overview, $symptoms, $causes, $riskFactors, $diagnosis, $treatment, $prevention, $whenToSeeDoctor]) {
            Disease::updateOrCreate(
                ['slug' => Str::slug($name)],
                compact('name', 'category', 'overview', 'symptoms', 'causes', 'diagnosis', 'treatment', 'prevention') + [
                    'risk_factors' => $riskFactors,
                    'when_to_see_doctor' => $whenToSeeDoctor,
                    'is_active' => true,
                ]
            );
        }
    }
}
